71		public List<DispatchReceiveDto> restoreConstructionSchedulePartial(Long projectOrderId) {
72			List<DispatchReceiveDto> res = new ArrayList<>();
73			List<ProjectOrderStatusLogDto> constructionList = constructionScheduleRpcService.queryConstructionScheduleDetailPartial(projectOrderId);
74			for (ProjectOrderStatusLogDto c : constructionList) {
75				String actionName = "";
76				Integer actionType = 0;
77				String receiptType = "";
78				if (!StatusEnum.WORK_PREPARE.getCode().equals(c.getTargetStatus())
79						&& !StatusEnum.BEFORE_WORK_DISCLOSURE.getCode().equals(c.getTargetStatus())) {
80					continue;
81				} else if (StatusEnum.WORK_PREPARE.getCode().equals(c.getTargetStatus())) {
82					receiptType = String.valueOf(StatusEnum.WORK_PREPARE.getCode());
83					actionName = DispatchReceiveActionTypeEnum.OFFICIALLY_SIGNED.getDesc();
84					actionType = DispatchReceiveActionTypeEnum.OFFICIALLY_SIGNED.getCode();
85				} else if (StatusEnum.BEFORE_WORK_DISCLOSURE.getCode().equals(c.getTargetStatus())) {
86					receiptType = String.valueOf(StatusEnum.BEFORE_WORK_DISCLOSURE.getCode());
87					actionName = DispatchReceiveActionTypeEnum.PENDING_START_WORK.getDesc();
88					actionType = DispatchReceiveActionTypeEnum.PENDING_START_WORK.getCode();
89				}
90				DispatchReceiveDto dispatchReceiveDto = new DispatchReceiveDto();
91				dispatchReceiveDto.setActionName(actionName);
92				dispatchReceiveDto.setActionType(actionType);
93				dispatchReceiveDto.setReceiptNo(receiptType);
94				dispatchReceiveDto.setReceiptType(DispatchReceiptTypeEnum.RECEIPT_SCHEDULE.getCode());
95				dispatchReceiveDto.setFlowMainNo(String.valueOf(projectOrderId));
96				dispatchReceiveDto.setSourceSystem(SystemMappingEnum.CONSTRUCTION_SCHEDULE.getName());
97				dispatchReceiveDto.setOperationTime(c.getCtime());
98				res.add(dispatchReceiveDto);
99			}
100			return res;
101		}
