121		public Map<String, Integer> queryCalendarByYear(Integer year) throws RpcException {
122			Map<Integer, Integer> typeBitmaskMap = new HashMap<>();
123			for (ConstructionCalendarTypeEnum cal : ConstructionCalendarTypeEnum.values()) {
124				typeBitmaskMap.put((int) cal.getValue(), cal.getBitmask());
125			}
126	
127			Map<String, Integer> res = new HashMap<>();
128			List<ConstructionCalendarDTO> calendars = constructionScheduleRpcService.getCalendar(year);
129			for (ConstructionCalendarDTO calendar : calendars) {
130				Integer bitmask = calendar.getCalendarTypeList().stream()
131						.map(type -> typeBitmaskMap.get(type.intValue()))
132						.reduce(0, Integer::sum);
133				res.put(calendar.getDate(), bitmask);
134			}
135			return res;
136		}
