84		private void asyncSendIndicatorChangeMsg(IndicatorCalculationContext indicatorCalculationContext) {
85			//异步发送指标动作变更消息
86			Set<String> updatedEval = indicatorCalculationContext.getUpdatedEval();
87			//如果本次没有变更 更新的
88			if(updatedEval.isEmpty()){
89				return;
90			}
91			List<IndicatorEvalValBO.IndicatorEvalSDO> baseEval = indicatorCalculationContext.getBaseEval();
92			List<IndicatorEvalValBO.IndicatorEvalSDO> cusEval = indicatorCalculationContext.getCusEval();
93	
94			// 将第二个列表的元素添加到新的列表中
95			IndicatorChangedEvent indicatorChangedEvent = IndicatorChangedEvent.builder()
96				.orderNo(indicatorCalculationContext.getIndicatorOrderBO().getOrderNo())
97				.projectOrderId(StringUtils.isNotBlank(indicatorCalculationContext.getIndicatorOrderBO().getProjectOrderId())?Long.valueOf(indicatorCalculationContext.getIndicatorOrderBO().getProjectOrderId()):-1L)
98				.branchCode(indicatorCalculationContext.getIndicatorOrderBO().getBranchCode())
99				.baseEval(baseEval)
100				.cusEval(cusEval)
101				.updatedEval(updatedEval)
102				.orderCreateTime(indicatorCalculationContext.getIndicatorOrderBO().getOrderCreateTime())
103				.qvyu(indicatorCalculationContext.getIndicatorOrderBO().getQvyv())
104				.categoryId(indicatorCalculationContext.getIndicatorOrderBO().getCategoryId())
105				.deliveryId(String.valueOf(indicatorCalculationContext.getIndicatorOrderBO().getDeliveryId()))
106				.taskMode(0)
107				.build();
