139		private IndicatorCalculationContext  buildIndicatorCalculationContext(String orderNo){
140			IndicatorCalculationContext indicatorCalculationContext = new IndicatorCalculationContext();
141			// 1. 获取订单的基础数据
142			IndicatorOrder indicatorOrder = indicatorOrderDao.getByOrderNo(orderNo);
143	
144			if(indicatorOrder == null){
145				return indicatorCalculationContext;
146			}
147			IndicatorOrderBO indicatorOrderBO = indicatorOrderService.getOrderBo(orderNo);
148			//设置订单基础信息
149			indicatorCalculationContext.setIndicatorOrderBO(indicatorOrderBO);
150	
151			List<FulfillmentNodeBo> hisFulfillmentNodeBos;
152			List<DispatchReceiveDto> dispatchReceiveDtos = null;
153			//两次查询 聚合出订单材料节点 + 工期节点信息
154			try {
155				dispatchReceiveDtos = ofcRpc.queryDispatchReceiveByMainFlowNo(orderNo);
156				hisFulfillmentNodeBos = this.convertToFulfillmentNode(dispatchReceiveDtos);
157				dispatchReceiveDtos = ofcRpc.queryDispatchReceiveByMainFlowNo(indicatorOrderBO.getProjectOrderId());
158				hisFulfillmentNodeBos.addAll(this.convertToFulfillmentNode(dispatchReceiveDtos));
159			} catch (RpcException e) {
160				throw new RuntimeException(e);
161			}
162			//转换历史节点信息
163			indicatorCalculationContext.setHisNodes(hisFulfillmentNodeBos);
164	
165	
166			//2.获取订单所匹配的所有指标数据
167			//2.1查询出所有的底线指标
168			List<IndicatorComputeRule> indicatorComputeRules = indicatorConfigBusinessQueryService.queryMatchedIndicatorBaseConfigList(indicatorOrderBO);
169	
170			//2.2 查询出所有的自定义指标
171			List<IndicatorCusConfigBO> indicatorCusConfigBOS = indicatorConfigBusinessQueryService.queryMatchedIndicatorCusConfigList(indicatorOrderBO);
172			ConfigMatchingTree configMatchingTree = new ConfigMatchingTree();
173			for (IndicatorCusConfigBO indicatorCusConfigBO : indicatorCusConfigBOS) {
174				configMatchingTree.addNode(indicatorCusConfigBO);
175			}
176			LOGGER.info(" 订单{}tree:{}",orderNo,JsonUtil.obj2JsonStr(configMatchingTree));
177			//建立查找的context
178			ConfigMatchingQueryContext configMatchingQueryContext = new ConfigMatchingQueryContext();
179			configMatchingQueryContext.setCategoryId(indicatorOrderBO.getCategoryId());
180			configMatchingQueryContext.setOrderMode(indicatorOrderBO.getOrderMode());
181			configMatchingQueryContext.setZhanqv(indicatorOrderBO.getZhanqv());
182			configMatchingQueryContext.setQvyu(indicatorOrderBO.getQvyv());
183			configMatchingQueryContext.setBranchCode(indicatorOrderBO.getBranchCode());
184			configMatchingQueryContext.setMerchantId(indicatorOrderBO.getMerchantId());
185			configMatchingQueryContext.setDeliveryId(String.valueOf(indicatorOrderBO.getDeliveryId()));
186	
187			//自定义指标
188			configMatchingTree.queryMatchedIndicators(configMatchingQueryContext);
189	
190			LOGGER.info("订单 {} matched cus indicator:{}", orderNo,JsonUtil.obj2JsonStr(configMatchingQueryContext));
191	
192			List<IndicatorComputeRule> matchedCusIndicatorList =
193				Lists.newArrayList(configMatchingQueryContext.getIndicatorCusMap().values());
194			indicatorCalculationContext.setIndicatorCusBOList(matchedCusIndicatorList);
195			//插入底线指标
196			indicatorCalculationContext.setIndicatorBaseBOList(indicatorComputeRules);
197	
198			//当前结果要先存进去
199			indicatorCalculationContext.setBaseEval(indicatorOrderBO.getBaseEvalResult() != null ? indicatorOrderBO.getBaseEvalResult():
200				new ArrayList<>() );
201			indicatorCalculationContext.setCusEval(indicatorOrderBO.getCusEvalResult() !=null ? indicatorOrderBO.getCusEvalResult() :
202			new ArrayList<>());
203	
204			indicatorCalculationContext.setUpdatedEval(new HashSet<>());
205	
206			return indicatorCalculationContext;
207		}
