216		private void calculateIndicator(IndicatorCalculationContext indicatorCalculationContext) {
217			//1.找出所有本次可以计算的指标
218			List<IndicatorComputeRule> indicatorBaseBOList = indicatorCalculationContext.getIndicatorBaseBOList();
219			//计算基础指标 这里需要信任完全过滤好了
220	
221			for (IndicatorComputeRule indicatorBO : indicatorBaseBOList) {
222					this.executeBaseCalculationRuleByNodeTo(indicatorCalculationContext, indicatorBO);
223			}
224			List<IndicatorComputeRule> indicatorCusConfigBOListi = indicatorCalculationContext.getIndicatorCusBOList();
225			for (IndicatorComputeRule indicatorBO : indicatorCusConfigBOListi) {
226				this.executeCusCalculationRuleByNodeTo(indicatorCalculationContext, indicatorBO);
227			}
228		}
