411		private void processOrder(List<ExtendedEdgeRule> ruleList, IndicatorOrder order, Map<String, NodeTimeTrackV2> timeV2,
412								  EventNode eventNode, Map<LocalDateTime, Integer> calendars) {
413			String indicatorName = eventNode.getEdgeInList()
414					.stream()
415					.flatMap(edge -> edge.getRuleList().stream())
416					.map(EdgeRule::getIndicatorName)
417					.findFirst()
418					.orElse(null);
419			FigureRes figureRes = processCommon(ruleList, order, null, timeV2, eventNode, indicatorName, calendars);
420			if (order != null) {
421				List<IndicatorEvalSDO> baseEvalSDOS = mergeIndicator(
422						Optional.ofNullable(JSONArray.parseArray(order.getBaseEvalResultNew(), IndicatorEvalSDO.class)).orElse(Lists.newArrayList()),
423						figureRes.getBaseEvalResult()
424				);
425				List<IndicatorEvalSDO> cusEvalSDOS = mergeIndicator(
426						Optional.ofNullable(JSONArray.parseArray(order.getCusEvalResultNew(), IndicatorEvalSDO.class)).orElse(Lists.newArrayList()),
427						figureRes.getCusEvalResult()
428				);
429				// 清理历史数据
430				// 如果cusEvalSDOS已经重算完成, checkTime应该为false
431				// checkTime = true说明没有命中版本, 则版本信息错误, 可以清楚该指标
432				List<IndicatorEvalSDO> remove = cusEvalSDOS.stream()
433						.filter(item -> item.getIndicatorName().equals(figureRes.getIndicatorName()) && item.getCheckTime() != null && item.getCheckTime())
434						.collect(Collectors.toList());
435				if (!remove.isEmpty()) {
436					LOGGER.info("processProjectOrder清理历史数据: {}", JsonUtil.obj2JsonStr(remove));
437				}
438				cusEvalSDOS.removeIf(item -> item.getIndicatorName().equals(figureRes.getIndicatorName()) && item.getCheckTime() != null && item.getCheckTime());
439	
440				LOGGER.info("refillPlaceOrder before: order:{}, base:{}, cus: {}", order, JsonUtil.obj2JsonStr(baseEvalSDOS), JsonUtil.obj2JsonStr(cusEvalSDOS));
441				refillPlaceOrder(order, baseEvalSDOS, cusEvalSDOS);
442				LOGGER.info("refillPlaceOrder after: order:{}, base:{}, cus: {}", order, JsonUtil.obj2JsonStr(baseEvalSDOS), JsonUtil.obj2JsonStr(cusEvalSDOS));
443				updateOrder(order, baseEvalSDOS, cusEvalSDOS);
444				LOGGER.info("refillPlaceOrder figureRes:{}", JsonUtil.obj2JsonStr(figureRes));
445				Integer taskType = indicatorChangedListener.getTaskType(figureRes.getIndicatorName());
446	
447				if (taskType != null && !FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode().equals(taskType)) {
448					// 下单及时不在这里同步, 在IndicatorProjectOrder同步
449					String deliveryId = DeliveryTypeEnum.WAREHOUSE.getType().equals(order.getDeliveryType()) ? order.getDeliveryId() : order.getSupplierId();
450					boolean update = updateFulfillmentTask(order.getOrderNo(), order.getProjectOrderId(), order.getCategoryId(), deliveryId,
451							figureRes.getFigureTime(), taskType, DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(order.getSecondType()));
452					update = update || (order.getBranchCode() != null && apolloConfig.getBeijingBranchCode().contains(order.getBranchCode()));
453					if (update && "送达及时".equals(figureRes.getIndicatorName())) {
454						IndicatorChangedEvent indicatorChangedEvent = IndicatorChangedEvent.builder()
455								.orderNo(order.getOrderNo())
456								.projectOrderId(Long.valueOf(order.getProjectOrderId()))
457								.branchCode(order.getBranchCode())
458								.baseEval(baseEvalSDOS)
459								.cusEval(cusEvalSDOS)
460								.updatedEval(new HashSet<>(Collections.singletonList(figureRes.getIndicatorName())))
461								.orderCreateTime(order.getCtime())
462								.qvyu(order.getQvyv())
463								.categoryId(order.getCategoryId())
464								.deliveryId(order.getDeliveryId())
465								.flowType(DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(order.getSecondType()) ?
466										FlowTypeEnum.REVERSE_ORDER.getCode() : FlowTypeEnum.NORMAL_ORDER.getCode())
467								.taskMode(TaskModeEnum.ORIGIN.getTaskMode())
468								.build();
469						applicationEventPublisher.publishEvent(indicatorChangedEvent);
470					}
471				}
472			}
473		}
