533		/**
534		 * 预加载该项目下汰换的下单任务（task_type=6）创建时间
535		 * key: categoryId_deliveryId → FulfillmentTask.createTime
536		 */
537		private Map<String, Date> buildReplacementPlaceOrderCreateTimeMap(String projectOrderId) {
538			// 查本项目下的下单任务（task_type=6）
539			FulfillmentTaskExample taskExample = new FulfillmentTaskExample();
540			taskExample.createCriteria()
541					.andProjectCodeEqualTo(projectOrderId)
542					.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())
543					.andStatusNotEqualTo(FulfillmentTaskStatusEnum.CANCELED.getTypeCode())
544					.andIsDeleteEqualTo((byte) 0);
545			List<FulfillmentTask> placeOrderTasks = fulfillmentTaskMapper.selectByExample(taskExample);
546			if (CollectionUtils.isEmpty(placeOrderTasks)) {
547				return Collections.emptyMap();
548			}
549	
550			// 查本项目下标记为汰换的 ext 记录
551			FulfillmentTaskExtExample extExample = new FulfillmentTaskExtExample();
552			extExample.createCriteria()
553					.andProjectOrderIdEqualTo(projectOrderId)
554					.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())
555					.andReplacementEqualTo((byte) 1);
556			List<FulfillmentTaskExt> extList = fulfillmentTaskExtMapper.selectByExample(extExample);
557			if (CollectionUtils.isEmpty(extList)) {
558				return Collections.emptyMap();
559			}
560			Set<Long> replacementTaskIds = extList.stream().map(FulfillmentTaskExt::getTaskId).collect(Collectors.toSet());
561	
562			// 仅保留汰换的下单任务，key: categoryId_deliveryId → createTime
563			return placeOrderTasks.stream()
564					.filter(t -> replacementTaskIds.contains(t.getId()))
565					.collect(Collectors.toMap(
566							t -> t.getCategoryId() + "_" + t.getDeliveryId(),
567							FulfillmentTask::getCreateTime,
568							(v1, v2) -> v1));
569		}
