830		private List<Timeline> calculateTimelines(List<ExtendedEdgeRule> edgeRules, Map<String, NodeTimeTrackV2> timeV2,
831												  String orderNo,
832												  EventNode eventNode) {
833			List<Timeline> result = new ArrayList<>();
834			for (ExtendedEdgeRule extendedEdgeRule : edgeRules) {
835				String codeFrom = extendedEdgeRule.getNodeFrom();
836				if (codeFrom.startsWith("f_") || codeFrom.startsWith("l_")) {
837					codeFrom = codeFrom.substring(2);
838				}
839				NodeTimeTrackV2 nodeTimeTrackV2 = timeV2.getOrDefault(codeFrom, null);
840				if (nodeTimeTrackV2 == null) {
841					continue;
842				}
843				List<NodeTimeTrackV2.TimeInfo> timeInfos = nodeTimeTrackV2.getTimeInfos();
844				if (CollectionUtils.isEmpty(timeInfos)) {
845					continue;
846				}
847				timeInfos = timeInfos.stream()
848					.filter(timeInfo -> orderNo == null || orderNo.equals(timeInfo.getOrderNo()))
849					.collect(Collectors.toList());
850				if (CollectionUtils.isEmpty(timeInfos)) {
851					timeInfos = nodeTimeTrackV2.getTimeInfos().stream()
852						.filter(timeInfo -> StringUtils.isEmpty(timeInfo.getOrderNo()))
853						.collect(Collectors.toList());
854				}
855				if (CollectionUtils.isEmpty(timeInfos)) {
856					continue;
857				}
858				List<TimeTrackRecord> timeTrackRecords = new ArrayList<>();
859				for (NodeTimeTrackV2.TimeInfo timeInfo : timeInfos) {
860					if (timeInfo.getCompleteTime() != null) {
861						timeTrackRecords.add(new TimeTrackRecord(1, timeInfo.getCompleteTime()));
862					} else if (timeInfo.getAssessmentTime() != null) {
863						timeTrackRecords.add(new TimeTrackRecord(0, timeInfo.getAssessmentTime()));
864					}
865				}
866				if (CollectionUtils.isEmpty(timeTrackRecords)) {
867					continue;
868				}
869				// f代表首次, l代表最后一次
870				if ("f".equals(eventNode.getPre())) {
871					timeTrackRecords.sort(Comparator.comparing(TimeTrackRecord::getTime));
872				} else if ("l".equals(eventNode.getPre())) {
873					timeTrackRecords.sort(Comparator.comparing(TimeTrackRecord::getTime).reversed());
874				}
875				TimeTrackRecord timeTrackRecord = timeTrackRecords.get(0);
876				Timeline timeline = new Timeline();
877				timeline.setStartTime(timeTrackRecord.getTime());
878				timeline.setRealFlag(timeTrackRecord.getRealFlag());
879				timeline.setEdgeRule(extendedEdgeRule);
880				result.add(timeline);
881			}
882			return result;
883		}
