886														EventNode eventNode, IndicatorOrder order, IndicatorProjectOrder projectOrder) {
887			IndicatorEvalSDO indicatorEvalSDO = new IndicatorEvalSDO();
888			ExtendedEdgeRule expectRuleUnit = calculatedTimeline.getExtendedEdgeRule();
889			indicatorEvalSDO.setIndicatorName(expectRuleUnit.getIndicatorName());
890			indicatorEvalSDO.setAssessmentRole(Lists.newArrayList(expectRuleUnit.getAssessmentRole().toString()));
891			indicatorEvalSDO.setVisibilityRole(Lists.newArrayList("1"));
