893			indicatorEvalSDO.setConfigType(expectRuleUnit.getConfigType());
894			indicatorEvalSDO.setExpectCompTime(DateUtil.formatTime(calculatedTimeline.getExpectTime()));
895			indicatorEvalSDO.setInterval(expectRuleUnit.getInterval() == null ? BigDecimal.ZERO : expectRuleUnit.getInterval());
896			indicatorEvalSDO.setAssessDayType(expectRuleUnit.getTimeType() != null ? expectRuleUnit.getTimeType() : 2);
897			indicatorEvalSDO.setStartTime(DateUtil.formatTime(calculatedTimeline.getStartTime()));
898			indicatorEvalSDO.setEndNode(RuleUnit.getRealNode(expectRuleUnit.getCodeTo()));
899			indicatorEvalSDO.setVersion(expectRuleUnit.getVersion());
900			indicatorEvalSDO.setMatchStartNode(expectRuleUnit.getNodeFrom());
901			indicatorEvalSDO.setEvaluation(0);
902			indicatorEvalSDO.setCheckTime(false);
903			// 轨迹结束节点时间  明确根据货单号过滤提取
904			NodeTimeTrackV2 codeToTrack = timeV2.getOrDefault(eventNode.getCategoryId() + "_" + eventNode.getOfcCode(), null);
905			if (codeToTrack != null) {
906				List<NodeTimeTrackV2.TimeInfo> timeInfos = codeToTrack.getTimeInfos().stream()
907					.filter(o -> Objects.nonNull(o.getCompleteTime()))
908					.sorted(Comparator.comparing(NodeTimeTrackV2.TimeInfo::getCompleteTime))
909					.collect(Collectors.toList());
910				for (NodeTimeTrackV2.TimeInfo timeInfo : timeInfos) {
911					if (order != null && order.getOrderNo().equals(timeInfo.getOrderNo()) && timeInfo.getCompleteTime() != null) {
912						indicatorEvalSDO.setRealCompTime(DateUtil.formatTime(timeInfo.getCompleteTime()));
913						break;
914					}
915					if (projectOrder != null && timeInfo.getCompleteTime() != null) {
916						indicatorEvalSDO.setRealCompTime(DateUtil.formatTime(timeInfo.getCompleteTime()));
917						break;
918					}
919				}
920			}
921			List<String> indicatorNodeList = Lists.newArrayList();
922			indicatorNodeList.addAll(expectRuleUnit.getCodeFrom());
923			indicatorNodeList.add(expectRuleUnit.getCodeTo());
924			indicatorEvalSDO.setIndicatorNodeList(indicatorNodeList.stream().map(RuleUnit::getRealNode).collect(Collectors.toList()));
925			indicatorEvalSDO.setRealFlag(calculatedTimeline.getRealFlag());
926			if (indicatorEvalSDO.getRealCompTime() != null
927					&& indicatorEvalSDO.getExpectCompTime() != null
928					&& DateUtil.string2Date(indicatorEvalSDO.getRealCompTime()).after(DateUtil.string2Date(indicatorEvalSDO.getExpectCompTime()))) {
929				indicatorEvalSDO.setEvaluation(1);
930			}
931			return indicatorEvalSDO;
932		}
